import{_ as t,o,c as a,ah as d}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Deployment","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/deployment.md","filePath":"src/en/guide/deployment.md"}'),n={name:"en/guide/deployment.md"};function s(i,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><p>Production runs on <strong>edPage&#39;s cPanel</strong>, next to Naia and the NextBoxx website (ADR-007). The server has neither Composer nor Node: dependencies and assets are built in GitHub Actions, then shipped with the release.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>URL</td><td><code>https://kura.nextboxx.net</code></td></tr><tr><td>Server</td><td>edPage cPanel, Apache, AutoSSL</td></tr><tr><td>PHP</td><td>8.3 (MultiPHP), extensions <code>pdo_mysql</code>, <code>mbstring</code>, <code>openssl</code>, <code>sodium</code>, <code>dom</code>, <code>xmlreader</code>, <code>fileinfo</code>, <code>zip</code>, <code>gd</code></td></tr><tr><td>Database</td><td>MySQL, database and user prefixed by the cPanel account</td></tr><tr><td>Deployment</td><td>GitHub Actions → <strong>Deploy to cPanel</strong>, started manually</td></tr><tr><td>Scripts</td><td><code>deploy/cpanel/</code> of the <code>kura-web</code> repository</td></tr></tbody></table><h2 id="what-a-deployment-does" tabindex="-1">What a deployment does <a class="header-anchor" href="#what-a-deployment-does" aria-label="Permalink to &quot;What a deployment does&quot;">​</a></h2><ol><li><strong>Build</strong>: the workflow refuses a commit whose <code>lint-test</code> CI is not green, unless <code>force</code> is ticked. It builds the assets (<code>pnpm build</code>) and installs the production PHP dependencies (<code>composer install --no-dev</code>).</li><li><strong>Upload</strong>: rsync of the release to the account. <strong>Never</strong> touched: <code>.env</code>, the OAuth keys (<code>storage/oauth-*.key</code>), <code>storage/app</code> (candidature documents, agreements, invoices, backups), <code>storage/logs</code>, <code>storage/framework</code>, the <code>public/storage</code> link, nor anything cPanel drops there (root <code>.htaccess</code>, <code>.well-known</code>, <code>cgi-bin</code>, <code>error_log</code>). The workflow writes the subdomain&#39;s PHP version back into <code>public/.htaccess</code>, otherwise Apache would fall back to PHP 8.2 and Kura would not boot.</li><li><strong><code>deploy.sh</code></strong>: <code>package:discover</code>, OAuth key check, database backup (<code>storage/app/backups/db-*.sql.gz</code>, the last 10 kept), maintenance mode, migrations, <code>RoleSeeder</code>, caches, queue restart, cron install on first deployment, back online.</li><li><strong>Check</strong>: <code>GET /up</code> must answer <code>200</code>.</li></ol><p>A deployment that fails after entering maintenance <strong>leaves the site in maintenance</strong>. This is deliberate: better a closed site than a half-migrated database. Fix, then run the deployment again; it brings the site back online.</p><h2 id="first-installation" tabindex="-1">First installation <a class="header-anchor" href="#first-installation" aria-label="Permalink to &quot;First installation&quot;">​</a></h2><h3 id="in-cpanel" tabindex="-1">In cPanel <a class="header-anchor" href="#in-cpanel" aria-label="Permalink to &quot;In cPanel&quot;">​</a></h3><ol><li><strong>Domains</strong>: create the subdomain with the application&#39;s <code>public</code> folder as web root (<code>/home/&lt;account&gt;/kura.nextboxx.net/public</code>). If the root points at the application folder itself, <code>.env</code> and the OAuth keys are exposed.</li><li><strong>MultiPHP Manager</strong>: PHP 8.3 for the subdomain. To change version later, change it here <strong>and</strong> <code>CPANEL_PHP_BIN</code>, then redeploy: the deployment rewrites the setting.</li><li><strong>PHP Extensions</strong>: enable the extensions from the table above (<code>dom</code> and <code>gd</code> serve the PDFs, <code>zip</code> and <code>xmlreader</code> the spreadsheet imports and exports).</li><li><strong>MySQL Databases</strong>: a database and its user, with all privileges.</li><li><strong>Email Accounts</strong>: the sending address (for instance <code>kura@nextboxx.net</code>).</li><li><strong>SSH Access</strong>: generate a dedicated key on a workstation (<code>ssh-keygen -t ed25519 -C kura-deploy -f kura-deploy</code>), import the public key into cPanel, then delete the private key from the workstation once copied into GitHub.</li></ol><h3 id="in-github" tabindex="-1">In GitHub <a class="header-anchor" href="#in-github" aria-label="Permalink to &quot;In GitHub&quot;">​</a></h3><p>In <code>kura-web</code> → <strong>Settings → Environments → <code>production</code></strong>:</p><table tabindex="0"><thead><tr><th>Secret</th><th>Content</th></tr></thead><tbody><tr><td><code>CPANEL_SSH_KEY</code></td><td>Deployment SSH private key</td></tr><tr><td><code>CPANEL_HOST</code>, <code>CPANEL_PORT</code>, <code>CPANEL_USER</code></td><td>SSH access to the account (<code>server.sedver.com</code>, <code>22</code>, the cPanel account)</td></tr><tr><td><code>CPANEL_APP_PATH</code></td><td>Application folder, for instance <code>/home/&lt;account&gt;/kura.nextboxx.net</code></td></tr><tr><td><code>CPANEL_PHP_BIN</code></td><td><code>/opt/cpanel/ea-php83/root/usr/bin/php</code></td></tr><tr><td><code>KURA_ENV_FILE</code></td><td>The full <code>.env</code>, written from <code>deploy/cpanel/.env.production.example</code>, with an empty <code>APP_KEY</code>. Only used for the installation</td></tr></tbody></table><p>In <code>KURA_ENV_FILE</code>, <code>NEXTBOXX_SITE_API_KEY</code> must hold exactly the <code>KURA_SITE_API_KEY</code> configured on the NextBoxx website. Empty, Kura refuses every call from the website. <code>SEVE_*</code> and <code>WHATSAPP_*</code> may stay empty at first.</p><h3 id="running-the-installation" tabindex="-1">Running the installation <a class="header-anchor" href="#running-the-installation" aria-label="Permalink to &quot;Running the installation&quot;">​</a></h3><p>Actions → <strong>Deploy to cPanel</strong>, <code>ref</code> = <code>master</code>, <strong>install</strong> ticked. <code>install.sh</code>:</p><ul><li>refuses if PHP cannot be found, if the release has no <code>vendor/</code>, if the server already has a <code>.env</code>, or if the URL, database, its password or the sender address is missing;</li><li>writes <code>.env</code> (mode <code>600</code>), generates <code>APP_KEY</code> and the OAuth keys;</li><li>runs <code>deploy.sh</code>, without a backup since the database is empty.</li></ul><h3 id="after-the-installation" tabindex="-1">After the installation <a class="header-anchor" href="#after-the-installation" aria-label="Permalink to &quot;After the installation&quot;">​</a></h3><ol><li><p>Create the first administrator, in the application folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users:create-admin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;name&gt;&quot;</span></span></code></pre></div><p>The password is requested on screen, never passed as an argument. The account is verified and holds the Administrator role.</p></li><li><p><strong>Copy to a safe place</strong> the server&#39;s <code>.env</code> and <code>storage/oauth-*.key</code>. Losing <code>APP_KEY</code> makes encrypted data unreadable (2FA secrets, queued jobs). Losing or replacing the OAuth keys signs every Sève user out and invalidates issued tokens.</p></li><li><p>Delete the <code>KURA_ENV_FILE</code> secret, now useless: <code>.env</code> lives on the server.</p></li></ol><h2 id="connecting-seve-and-whatsapp" tabindex="-1">Connecting Sève and WhatsApp <a class="header-anchor" href="#connecting-seve-and-whatsapp" aria-label="Permalink to &quot;Connecting Sève and WhatsApp&quot;">​</a></h2><p>An instance keeps its <code>.env</code>, which a deployment never rewrites. A key is therefore set by hand in the server&#39;s <code>.env</code> (cPanel › File Manager); the next deployment picks it up, or <code>php artisan optimize</code> immediately.</p><ul><li><strong>Sève</strong>: as long as <code>SEVE_URL</code> or <code>SEVE_WS_TOKEN</code> is empty, nothing is sent; changes wait in the queue and go out as soon as both are set. Once <code>SEVE_URL</code> is set, <code>php artisan seve:client</code> creates Sève&#39;s OAuth client and prints the secret to enter in Moodle&#39;s OAuth 2 issuer.</li><li><strong>WhatsApp</strong>: with <code>WHATSAPP_TOKEN</code> and <code>WHATSAPP_PHONE_NUMBER_ID</code> empty, messages go out by email only.</li></ul><h2 id="crons" tabindex="-1">Crons <a class="header-anchor" href="#crons" aria-label="Permalink to &quot;Crons&quot;">​</a></h2><p>Installed by <code>deploy.sh</code> on the first deployment. Otherwise add them in cPanel (Cron Jobs) from <code>deploy/cpanel/crontab.example</code>:</p><table tabindex="0"><thead><tr><th>Task</th><th>Frequency</th><th>Purpose</th></tr></thead><tbody><tr><td><code>schedule:run</code></td><td>Every minute</td><td>Fires all scheduled tasks</td></tr><tr><td><code>queue:work --stop-when-empty --max-time=55 --tries=3</code></td><td>Every minute</td><td>Sends notifications, emails and jobs</td></tr><tr><td>Cron log cleanup</td><td>Weekly</td><td>Keeps the disk from filling up</td></tr></tbody></table><p>Without <code>schedule:run</code>, no scheduled task runs: no Sève sync, no billing, no reminders, no cohort transitions. Without the worker, no notification is sent, <strong>with no visible error</strong>.</p><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to &quot;Common operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Procedure</th></tr></thead><tbody><tr><td>Deploy</td><td>Actions → <strong>Deploy to cPanel</strong>, <code>ref</code> = <code>master</code> (or a branch, tag, commit), <strong>install</strong> unticked</td></tr><tr><td>An email is not arriving</td><td><code>storage/logs/cron-queue.log</code>, then <code>php artisan queue:failed</code>, fix, <code>php artisan queue:retry all</code></td></tr><tr><td>Restore a backup</td><td><code>php artisan down</code>, then <code>gunzip -c storage/app/backups/db-….sql.gz | mysql &lt;database&gt;</code> with the <code>.env</code> credentials</td></tr><tr><td>Know the live version</td><td><code>storage/app/release.json</code> (branch, commit, date)</td></tr><tr><td>Read the logs</td><td><code>storage/logs/laravel-YYYY-MM-DD.log</code></td></tr></tbody></table><h2 id="good-practices" tabindex="-1">Good practices <a class="header-anchor" href="#good-practices" aria-label="Permalink to &quot;Good practices&quot;">​</a></h2><ul><li><strong>Never edit code by hand on the server</strong>: the next deployment would overwrite it. Only <code>.env</code> is edited in place.</li><li><strong>Back up before a risky migration</strong>: the deployment does it, but a manual operation deserves its own backup.</li><li><strong>Test restores</strong>: a backup never restored is not a backup.</li><li><strong>Watch <code>/up</code></strong> after every deployment, then the queues and logs in the following hour.</li><li><strong>Never version secrets</strong>: <code>.env</code>, OAuth keys and API keys live in the GitHub environment or on the server, never in the repository.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/kura-guide/en/guide/development.html">Development</a> for commands and quality.</li><li><a href="/kura-guide/en/guide/integrations.html">Integrations</a> for Sève, WhatsApp and scheduled commands.</li></ul>',31)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
